#include <hexi/hexi.h>
#include <cstdint>
#include <span>

struct PacketHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    // Create a buffer_adaptor from the span
    hexi::buffer_adaptor adaptor(buffer);

    // Get the read pointer to access the raw data
    const uint8_t* read_ptr = adaptor.read_ptr();

    // Check if we have enough data available for the header
    constexpr size_t header_size = sizeof(PacketHeader);
    if (adaptor.size() < header_size) {
        // Handle insufficient data - return default/zero-initialized header
        return PacketHeader{0, 0, 0};
    }

    // Create a binary_stream for zero-copy operations
    hexi::binary_stream stream(adaptor);

    // Get a zero-copy view of the header data as a span
    std::span<const uint8_t> header_span(read_ptr, header_size);

    // Read the header fields using binary_stream
    PacketHeader header;
    header.magic = stream.read<uint32_t>();
    header.version = stream.read<uint16_t>();
    header.flags = stream.read<uint16_t>();

    return header;
}
```

