#include <hexi/detail/intrusive_storage.h>
#include <vector>
#include <cstdint>

template<size_t block_size = 1024>
std::vector<uint8_t> preview_data_without_consuming(const hexi::detail::intrusive_storage<block_size>& storage, size_t bytes_to_preview) {
    // Limit preview to actual readable size
    size_t actual_bytes = (bytes_to_preview < storage.size()) ? bytes_to_preview : storage.size();

    std::vector<uint8_t> result(actual_bytes);

    // Copy data using subscript operator without advancing read pointer
    for (size_t i = 0; i < actual_bytes; ++i) {
        result[i] = storage[i];
    }

    return result;
}

template<size_t block_size = 1024>
struct BufferStatus {
    size_t readable_size;
    size_t free_space;
};

template<size_t block_size = 1024>
BufferStatus<block_size> check_buffer_status(const hexi::detail::intrusive_storage<block_size>& storage) {
    BufferStatus<block_size> status;

    // Get readable size (data available for reading)
    status.readable_size = storage.size();

    // Calculate free space (capacity - readable_size)
    status.free_space = block_size - status.readable_size;

    return status;
}

template<size_t block_size = 1024>
void reset_buffer(hexi::detail::intrusive_storage<block_size>& storage) {
    // Reset the buffer by reading all available data
    // This advances the read pointer to match the write pointer
    std::vector<uint8_t> temp(storage.size());
    if (!temp.empty()) {
        storage.read(temp.data(), temp.size());
    }
}
