std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    // Create a file_buffer for the given file path
    hexi::file_buffer buffer(file_path);

    // Check if the buffer is in a valid state
    if (!buffer) {
        return {};
    }

    // Ensure we don't read more than available
    size_t actual_bytes = std::min(bytes_to_read, buffer.size());

    // Create a vector to hold the data
    std::vector<uint8_t> data(actual_bytes);

    // Read data from the file into the vector
    if (actual_bytes > 0) {
        buffer.read(data.data(), actual_bytes);
    }

    // Check if read was successful
    if (!buffer) {
        return {};
    }

    return data;
}

std::vector<uint8_t> preview_file_data(const std::filesystem::path& file_path, size_t bytes_to_preview) {
    // Create a file_buffer for the given file path
    hexi::file_buffer buffer(file_path);

    // Check if the buffer is in a valid state
    if (!buffer) {
        return {};
    }

    // Ensure we don't preview more than available
    size_t actual_bytes = std::min(bytes_to_preview, buffer.size());

    // Create a vector to hold the data
    std::vector<uint8_t> data(actual_bytes);

    // Copy data without advancing the read pointer
    if (actual_bytes > 0) {
        buffer.copy(data.data(), actual_bytes);
    }

    // Check if copy was successful
    if (!buffer) {
        return {};
    }

    return data;
}

void write_file_data(const std::filesystem::path& file_path, const std::vector<uint8_t>& data) {
