TEST(FileBuffer, ReadWriteUint32) {
    std::filesystem::path test_file = "test_uint32.bin";
    uint32_t original_value = 12345678;

    write_uint32_to_file(test_file, original_value);
    uint32_t read_value = read_uint32_from_file(test_file);

    EXPECT_EQ(original_value, read_value);

    std::filesystem::remove(test_file);
}

