```cpp
#include <hexi/static_buffer.h>
#include <vector>
#include <cstdint>

template<size_t buffer_size = 1024>
void write_data_to_buffer(hexi::static_buffer<std::byte, buffer_size>& buffer, const std::vector<uint8_t>& data) {
    // Write data to the buffer
    // Convert uint8_t to std::byte and write to buffer
    for (const auto& byte : data) {
        buffer.write(static_cast<std::byte>(byte));
    }
}

template<size_t buffer_size = 1024>
std::vector<uint8_t> read_data_from_buffer(hexi::static_buffer<std::byte, buffer_size>& buffer, size_t bytes_to_read) {
    // Read data from the buffer
    std::vector<uint8_t> result;
    result.reserve(bytes_to_read);

    // Determine how many bytes we can actually read (min of requested and available)
    size_t bytes_available = buffer.size();
    size_t bytes_to_actually_read = (bytes_to_read < bytes_available) ? bytes_to_read : bytes_available;

    // Read bytes from the buffer
    for (size_t i = 0; i < bytes_to_actually_read; ++i) {
        std::byte byte_value;
        buffer.read(&byte_value, 1);
        result.push_back(static_cast<uint8_t>(byte_value));
    }

    return result;
}
```

The implementation:

1. **`write_data_to_buffer`**: Iterates through the input vector and writes each byte to the buffer after converting from `uint8_t` to `std::byte`.

2. **`read_data_from_buffer`**: 
   - Creates a result vector to store the read data
   - Determines how many bytes can actually be read (minimum of requested bytes and available bytes in buffer)
   - Reads bytes one at a time from the buffer using the `read()` method
   - Converts each `std::byte` back to `uint8_t` and adds it to the result vector
   - Returns the vector containing the read data

