#include <gtest/gtest.h>
#include <hexi/pmc/binary_stream_writer.h>
#include <hexi/pmc/binary_stream_reader.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <string>
#include <vector>

// Include the implementation
#include "implementation.hpp"

TEST(PMCBinaryStream, WriteReadString) {
    std::vector<std::byte> buffer(1000);
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    hexi::pmc::buffer& buf_ref = adaptor;
    hexi::pmc::binary_stream_writer writer(static_cast<hexi::pmc::buffer_write&>(buf_ref));
    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));

    std::string original = "Hello World";
    write_string_to_stream(writer, original);

    std::string result = read_string_from_stream(reader);

    EXPECT_EQ(original, result);
}

TEST(PMCBinaryStream, WriteReadEmptyString) {
    std::vector<std::byte> buffer(1000);
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    hexi::pmc::buffer& buf_ref = adaptor;
    hexi::pmc::binary_stream_writer writer(static_cast<hexi::pmc::buffer_write&>(buf_ref));
    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));

    std::string original = "";
    write_string_to_stream(writer, original);

    std::string result = read_string_from_stream(reader);

    EXPECT_EQ(original, result);
}

TEST(PMCBinaryStream, WriteReadLongString) {
    std::vector<std::byte> buffer(1000);
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    hexi::pmc::buffer& buf_ref = adaptor;
    hexi::pmc::binary_stream_writer writer(static_cast<hexi::pmc::buffer_write&>(buf_ref));
    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));

    std::string original(100, 'A');
    write_string_to_stream(writer, original);

    std::string result = read_string_from_stream(reader);

    EXPECT_EQ(original, result);
}

