Looking at the code fragments and the Hexi library's `buffer_adaptor` API, I can see how to implement the required functions. Based on the test examples and the API documentation, here's the complete implementation:

```cpp
#include <hexi/pmc/buffer_adaptor.h>
#include <vector>
#include <cstdint>

void write_data_to_buffer(hexi::pmc::buffer_adaptor<std::vector<std::byte>>& buffer, uint32_t value, const void* data, std::size_t length) {
    // Write the integer value to the buffer
    buffer.write(&value, sizeof(uint32_t));

    // Write the byte array to the buffer
    buffer.write(data, length);
}

void read_data_from_buffer(hexi::pmc::buffer_adaptor<std::vector<std::byte>>& buffer, uint32_t& value, void* data, std::size_t length) {
    // Read the integer value from the buffer
    buffer.read(&value, sizeof(uint32_t));

    // Read the byte array from the buffer
    buffer.read(data, length);
}

struct BufferInfo {
    std::size_t size;
    std::size_t free_space;
};

BufferInfo get_buffer_info(hexi::pmc::buffer_adaptor<std::vector<std::byte>>& buffer) {
    BufferInfo info;

    // Get the current size (bytes available to read)
    info.size = buffer.size();

    // Calculate free space
    // For a vector-based buffer, we need to get the underlying buffer capacity
    // Free space = total capacity - current write position
    // Since buffer_adaptor tracks read/write offsets internally,
    // and the underlying vector can grow, the free_space concept here
    // represents the currently readable data size as "size" 
    // and we assume free_space as 0 for a read buffer or calculate based on capacity
    // However, based on the API, we'll use size for readable bytes
    // and free_space as the remaining capacity (vectors grow dynamically, so this is conceptual)
    info.free_space = 0; // std::vector grows dynamically, so free space is not limited

    return info;
}
```

