#include <gtest/gtest.h>
#include <hexi/shared.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <hexi/pmc/binary_stream_writer.h>
#include <hexi/pmc/binary_stream_reader.h>
#include <vector>
#include <cstdint>

// Include the implementation
#include "implementation.hpp"

TEST(Varint, EncodeDecodeSmall) {
    std::vector<std::byte> buffer(1000);
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    hexi::pmc::buffer& buf_ref = adaptor;
    hexi::pmc::binary_stream_writer writer(static_cast<hexi::pmc::buffer_write&>(buf_ref));
    std::size_t bytes_written = encode_varint(writer, std::uint8_t(127));

    EXPECT_EQ(1, bytes_written);

    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));
    std::uint8_t decoded = decode_varint<std::uint8_t>(reader);

    EXPECT_EQ(127, decoded);
}

TEST(Varint, EncodeDecodeMedium) {
    std::vector<std::byte> buffer(1000);
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    hexi::pmc::buffer& buf_ref = adaptor;
    hexi::pmc::binary_stream_writer writer(static_cast<hexi::pmc::buffer_write&>(buf_ref));
    encode_varint(writer, std::uint16_t(128));

    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));
    std::uint16_t decoded = decode_varint<std::uint16_t>(reader);

    EXPECT_EQ(128, decoded);
}

TEST(Varint, EncodeDecodeLarge) {
    std::vector<std::byte> buffer(1000);
    hexi::pmc::buffer_adaptor adaptor(buffer, hexi::init_empty);

    hexi::pmc::buffer& buf_ref = adaptor;
    hexi::pmc::binary_stream_writer writer(static_cast<hexi::pmc::buffer_write&>(buf_ref));
    encode_varint(writer, std::uint32_t(16384));

    hexi::pmc::binary_stream_reader reader(static_cast<hexi::pmc::buffer_read&>(buf_ref));
    std::uint32_t decoded = decode_varint<std::uint32_t>(reader);

    EXPECT_EQ(16384, decoded);
}

TEST(Varint, Roundtrip) {
    EXPECT_TRUE(encode_decode_roundtrip(std::uint8_t(0)));
    EXPECT_TRUE(encode_decode_roundtrip(std::uint8_t(127)));
    EXPECT_TRUE(encode_decode_roundtrip(std::uint16_t(128)));
    EXPECT_TRUE(encode_decode_roundtrip(std::uint32_t(16384)));
    EXPECT_TRUE(encode_decode_roundtrip(std::uint32_t(2097151)));
}

