#include <hexi/pmc/buffer_base.h>
#include <vector>
#include <cstddef>

class CustomBuffer : public hexi::pmc::buffer_base {
    std::vector<std::byte> data_;

public:
    // Return the current size of the buffer (number of bytes stored)
    std::size_t size() const override {
        return data_.size();
    }

    // Return true if the buffer is empty (size is 0), false otherwise
    bool empty() const override {
        return data_.empty();
    }

    // Helper method to add data (for testing)
    void add_data(const void* source, std::size_t length) {
        const std::byte* bytes = static_cast<const std::byte*>(source);
        data_.insert(data_.end(), bytes, bytes + length);
    }

    // Helper method to clear data (for testing)
    void clear() {
        data_.clear();
    }
};
```

The implementation:

1. **`size()`**: Returns `data_.size()` which gives the number of `std::byte` elements currently stored in the vector, representing the number of bytes in the buffer.

2. **`empty()`**: Returns `data_.empty()` which returns `true` if the vector has no elements (size is 0), and `false` otherwise.

Both methods are marked as `override` since they're implementing pure virtual methods from the `buffer_base` class, and both are `const` since they don't modify the buffer's state - they only query its current status.

