#include <hexi/pmc/buffer_read_adaptor.h>
#include <hexi/pmc/buffer_write_adaptor.h>
#include <vector>
#include <cstdint>
#include <cstring>

std::vector<uint8_t> write_and_read_data(const std::vector<uint8_t>& input_data) {
    // Create a buffer to hold the data
    std::vector<std::uint8_t> buffer;

    // Create write adaptor to write data to the buffer
    hexi::pmc::buffer_write_adaptor write_adaptor(buffer);

    // Check available space (for vectors, this typically returns max size or a large value)
    // The free() method returns available space before reallocation
    auto free_space = write_adaptor.free();

    // Write the input data to the buffer
    if (input_data.size() <= free_space || buffer.capacity() == 0) {
        write_adaptor.write(input_data.data(), input_data.size());
    }

    // Create read adaptor to read data back from the buffer
    hexi::pmc::buffer_read_adaptor read_adaptor(buffer);

    // Check the readable size
    auto readable_size = read_adaptor.size();

    // Create output vector to store read data
    std::vector<std::uint8_t> output_data(readable_size);

    // Read the data back from the buffer
    if (readable_size > 0) {
        read_adaptor.read(output_data.data(), readable_size);
    }

    return output_data;
}

std::vector<uint8_t> peek_data_without_advancing(const std::vector<uint8_t>& buffer_data, std::size_t peek_size) {
    // Create a mutable copy since adaptor might need non-const buffer
    std::vector<std::uint8_t> buffer = buffer_data;

    // Create read adaptor
    hexi::pmc::buffer_read_adaptor read_adaptor(buffer);

    // Get pointer to current read position
    const std::uint8_t* read_position = read_adaptor.read_ptr();

